WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, LENGTH(channel) AS channel_length, COALESCE(channel, 'DIRECT') AS channel_clean FROM promotions WHERE channel IS NOT NULL) SELECT id, channel, promo_code, starts_on, ends_on, channel_length, channel_clean, SUM(channel_length) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_channel_length, STDDEV_SAMP(channel_length) OVER (PARTITION BY promo_code) AS promo_code_stddev_samp_channel_length, RANK() OVER (PARTITION BY promo_code ORDER BY channel_length) AS channel_length_rank, AVG(channel_length) OVER (ORDER BY channel_length, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS channel_length_avg_5_prior, ROW_NUMBER() OVER (ORDER BY ends_on DESC, id) AS row_seq FROM base
